def mk2(seed, style):
    """Distinct signatures (paths), tight capacities."""
    rng=random.Random(seed+1000)
    if style=='distinct-tight':
        nodes=['n%d'%i for i in range(10)]; caps={n:rng.choice([2,3]) for n in nodes}
    elif style=='distinct-mid':
        nodes=['n%d'%i for i in range(16)]; caps={n:rng.choice([1,2,4]) for n in nodes}
    elif style=='distinct-wide':
        nodes=['n%d'%i for i in range(30)]; caps={n:rng.choice([1,2,3]) for n in nodes}
    seen=set(); paths=[]
    while len(paths)<22:
        k=rng.randint(3,min(9,len(nodes)))
        p=tuple(sorted(rng.sample(nodes,k)))
        if p in seen: continue
        seen.add(p); paths.append(p)
    flows=[]
    for i,p in enumerate(paths):
        H=rng.choice([8,40,256]); nd=rng.randint(0,(H-5)//2)
        kinds=['K']*(H-nd-2)+['D']*nd+['Q','T']
        rng.shuffle(kinds)
        flows.append({'id':'f%02d'%i,'path':list(p),'template':bytes(rng.randrange(256) for _ in range(H)).hex(),'kinds':''.join(kinds)})
    offers={}
    for i,f in enumerate(flows):
        H=len(f['template'])//2
        hb=bytearray(H)
        for pos,c in enumerate(f['kinds']):
            if c=='K': hb[pos]=int(f['template'][2*pos:2*pos+2],16)
            elif c=='Q': hb[pos]=3
            elif c=='T': hb[pos]=250
        offers[f['id']]=[{'header':bytes(hb).hex(),'count':10**6+(22-i)*7}]
    return {'mode':'plan','capacities':caps,'flows':flows,'warmup':0,'pinned':[],'offers':offers}

for style in ['distinct-tight','distinct-mid','distinct-wide']:
    for seed in range(3):
        req=mk2(seed,style)
        t=time.time(); out=run([req]); dt=time.time()-t
        ref,ben=exact(req); g=out[0]
        ok = ('selected' in g and g['saved']==ref['saved'] and len(g['selected'])==ref['count']) if 'saved' in ref else g=={'infeasible':True}
        print('%-14s seed%d %6.2fs saved=%s ref=%s %s' % (style, seed, dt, g.get('saved'), ref.get('saved'), 'OK' if ok else '*** BAD '+json.dumps(g)[:80]))
